// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import {
  ArrowLeftIcon,
  ChevronRightIcon,
  DownloadIcon,
  FileJsonIcon,
  MessageCircleIcon,
  PlusIcon,
  SlidersHorizontalIcon,
  UsersIcon,
  WrenchIcon,
  XIcon,
  BriefcaseBusinessIcon,
} from 'lucide-react'
import type { ReactNode } from 'react'

import { BrowserChrome, DemoStage, type Build } from '@/app/demos/stage'

import {
  CAPTIONS,
  CHATS,
  DEFAULT_ACTIVE,
  EXPORT_OPTIONS,
  FILE,
  FORMATS,
  HOME_ROWS,
  MESSAGES,
  OPEN_CHAT,
  PICKED_FORMAT,
  PRIVACY_ROWS,
  PRIVATE_ACTIVE,
} from './script'

const HOME_ICONS = [SlidersHorizontalIcon, BriefcaseBusinessIcon, DownloadIcon, WrenchIcon]
const BLUR = { filter: 'blur(5px)', duration: 0.35, ease: 'power2.out' }

const build: Build = ({ tl, q, qa, step, final, move, click, count, wait, cursorOut }) => {
  const openDrawer = () => {
    move('launcher')
    click('launcher')
    tl.fromTo(
      q('drawer'),
      { xPercent: -104, opacity: 0 },
      { xPercent: 0, opacity: 1, duration: 0.4, ease: 'power3.out', immediateRender: false },
      '<',
    )
  }
  const go = (from: string, to: string) => {
    tl.to(
      q(`view-${from}`),
      { xPercent: -30, opacity: 0, duration: 0.3, ease: 'power2.inOut' },
      '<',
    )
    tl.fromTo(
      q(`view-${to}`),
      { xPercent: 30, opacity: 0 },
      { xPercent: 0, opacity: 1, duration: 0.3, ease: 'power2.out', immediateRender: false },
      '<0.05',
    )
  }

  step(0)
  openDrawer()
  tl.from(
    qa('home-row'),
    { opacity: 0, x: -10, stagger: 0.05, duration: 0.3, immediateRender: false },
    '<0.2',
  )

  step(1, '+=0.5')
  move('home-row-enhancements')
  click('home-row-enhancements')
  go('home', 'enh')
  move('privacy-switch', { at: '+=0.2' })
  click('privacy-switch')
  tl.to(q('privacy-switch-fill'), { backgroundColor: '#25d366', duration: 0.2 }, '<')
  tl.to(q('privacy-switch-knob'), { x: 10, duration: 0.25, ease: 'back.out(2)' }, '<')
  tl.to(
    qa('privacy-check'),
    { backgroundColor: '#25d366', borderColor: '#25d366', duration: 0.15, stagger: 0.06 },
    '<',
  )
  tl.fromTo(
    qa('privacy-tick'),
    { scale: 0 },
    { scale: 1, duration: 0.2, stagger: 0.06, ease: 'back.out(3)', immediateRender: false },
    '<',
  )
  count('active', PRIVATE_ACTIVE, { from: DEFAULT_ACTIVE, at: '<', duration: 0.5 })
  tl.to(
    [...qa('blur-name'), ...qa('blur-msg'), ...qa('blur-preview'), q('blur-composer')],
    { ...BLUR },
    '<',
  )
  tl.to(qa('blur-photo'), { ...BLUR, filter: 'blur(4px)' }, '<')
  move('drawer-close', { at: '+=0.3' })
  click('drawer-close')
  tl.to(q('drawer'), { xPercent: -104, opacity: 0, duration: 0.35, ease: 'power3.in' }, '<')
  move('bubble-3', { at: '+=0.2', ax: 0.4 })
  tl.to(q('bubble-text-3'), { filter: 'blur(0px)', duration: 0.15 }, '<0.5')
  move('bubble-1', { at: '+=0.6', ax: 0.5, dy: 30 })
  tl.to(q('bubble-text-3'), { filter: 'blur(5px)', duration: 0.15 }, '<0.2')

  step(2, '+=0.3')
  tl.set(q('view-enh'), { opacity: 0 })
  tl.set(q('view-home'), { xPercent: 0, opacity: 1 })
  openDrawer()
  move('home-row-export', { at: '+=0.1' })
  click('home-row-export')
  go('home', 'export')
  move('export-chat', { at: '+=0.15' })
  click('export-chat')
  tl.fromTo(
    q('modal'),
    { opacity: 0, scale: 0.94 },
    { opacity: 1, scale: 1, duration: 0.3, ease: 'power3.out', immediateRender: false },
    '<',
  )
  move(`format-${PICKED_FORMAT}`)
  click(`format-${PICKED_FORMAT}`)
  tl.to(q('format-dot-0'), { scale: 0, duration: 0.15 }, '<')
  tl.fromTo(
    q(`format-dot-${PICKED_FORMAT}`),
    { scale: 0 },
    { scale: 1, duration: 0.2, ease: 'back.out(3)', immediateRender: false },
    '<',
  )
  move('export-go')
  click('export-go')
  tl.to(q('modal'), { opacity: 0, scale: 0.96, duration: 0.25 }, '+=0.25')
  tl.fromTo(
    q('toast'),
    { opacity: 0, y: 8 },
    { opacity: 1, y: 0, duration: 0.3, ease: 'power3.out', immediateRender: false },
    '<',
  )
  tl.fromTo(
    q('file'),
    { opacity: 0, y: -10 },
    { opacity: 1, y: 0, duration: 0.35, ease: 'power3.out', immediateRender: false },
    '<0.1',
  )
  cursorOut('<0.3')
  final()
  wait(1.3)

  tl.set(
    [q('drawer'), q('view-enh'), q('view-export'), q('modal'), q('toast'), q('file')],
    { opacity: 0 },
    0,
  )
  tl.set(qa('privacy-tick'), { scale: 0 }, 0)
  tl.set(q(`format-dot-${PICKED_FORMAT}`), { scale: 0 }, 0)
  tl.set(
    [
      ...qa('blur-name'),
      ...qa('blur-msg'),
      ...qa('blur-preview'),
      ...qa('blur-photo'),
      q('blur-composer'),
    ],
    { filter: 'blur(0px)' },
    0,
  )
}

function Check({ d, on }: { d?: string; on?: boolean }) {
  return (
    <span
      data-d={d}
      className={`flex size-2.5 shrink-0 items-center justify-center rounded-sm border ${on ? 'border-[#25d366] bg-[#25d366]' : 'border-white/30'}`}
    >
      <span
        data-d={d ? 'privacy-tick' : undefined}
        className="block size-1 rounded-[1px] bg-[#111b21]"
      />
    </span>
  )
}

function Heading({ title, children }: { title: string; children?: ReactNode }) {
  return (
    <div className="flex items-center gap-1.5 border-b border-white/10 px-2 py-1.5">
      <ArrowLeftIcon className="size-3 text-white/60" />
      <span className="flex-1 text-[10px] font-semibold">{title}</span>
      {children}
    </div>
  )
}

function Drawer() {
  return (
    <div
      data-d="drawer"
      className="absolute inset-y-0 left-9 z-10 flex w-[188px] flex-col border-r border-white/10 bg-[#111b21] opacity-0 shadow-2xl"
    >
      <div className="flex items-center justify-between border-b border-white/10 px-2 py-1.5">
        <span className="text-[11px] font-bold">
          ChatBoost <sup className="text-[7px] font-normal text-white/50">for WhatsApp</sup>
        </span>
        <span
          data-d="drawer-close"
          className="flex size-4 items-center justify-center rounded-full"
        >
          <XIcon className="size-3 text-white/70" />
        </span>
      </div>
      <div className="relative flex-1 overflow-hidden">
        <div data-d="view-home" className="absolute inset-0 space-y-0.5 p-1.5">
          {HOME_ROWS.map((row, index) => {
            const Icon = HOME_ICONS[index]
            return (
              <div
                key={row.id}
                data-d={`home-row home-row-${row.id}`}
                className="flex items-center gap-1.5 rounded-md px-1.5 py-1"
              >
                <span className="flex size-5 shrink-0 items-center justify-center rounded-full bg-[#25d366]/15">
                  <Icon className="size-2.5 text-[#25d366]" />
                </span>
                <span className="min-w-0">
                  <span className="block text-[9px] font-semibold">{row.title}</span>
                  <span className="block truncate text-[7.5px] text-white/50">{row.sub}</span>
                </span>
              </div>
            )
          })}
          <p className="px-1.5 pt-1 text-[8px] text-white/50">
            <span data-d="active">{DEFAULT_ACTIVE}</span> features active
          </p>
        </div>
        <div data-d="view-enh" className="absolute inset-0 opacity-0">
          <Heading title="Enhancements" />
          <div className="m-1.5 rounded-md bg-white/[0.04] p-1.5">
            <div className="flex items-start justify-between gap-2">
              <span>
                <span className="block text-[9px] font-semibold">Private Mode</span>
                <span className="block text-[7.5px] text-white/50">
                  Anti screen spying and deleted messages
                </span>
              </span>
              <span
                data-d="privacy-switch privacy-switch-fill"
                className="relative h-2.5 w-5 shrink-0 rounded-full bg-white/20"
              >
                <span
                  data-d="privacy-switch-knob"
                  className="absolute left-0.5 top-0.5 size-1.5 rounded-full bg-white"
                />
              </span>
            </div>
            <div className="mt-1.5 space-y-1">
              {PRIVACY_ROWS.map((row) => (
                <div key={row} className="flex items-center gap-1.5 text-[8.5px] text-white/80">
                  <Check d="privacy-check" />
                  {row}
                </div>
              ))}
            </div>
          </div>
        </div>
        <div data-d="view-export" className="absolute inset-0 opacity-0">
          <Heading title="Export">
            <DownloadIcon className="size-3 text-white/60" />
          </Heading>
          <div
            data-d="export-chat"
            className="m-1.5 flex items-center gap-1.5 rounded-md bg-white/[0.06] p-1.5"
          >
            <DownloadIcon className="size-3 text-[#25d366]" />
            <span className="min-w-0 flex-1">
              <span className="block text-[9px] font-semibold">Export chat</span>
              <span className="block text-[7.5px] text-white/50">
                Save the open chat as HTML, JSON, Excel, or CSV.
              </span>
            </span>
            <ChevronRightIcon className="size-3 text-white/50" />
          </div>
          <div className="mx-1.5 space-y-1">
            {['Contacts', 'Groups', 'Labels', 'Countries'].map((kind) => (
              <div
                key={kind}
                className="flex items-center gap-1.5 rounded-md px-1.5 py-1 text-[9px]"
              >
                <UsersIcon className="size-3 text-white/50" />
                <span className="flex-1">{kind}</span>
                <span className="size-2 rounded-full border border-white/30" />
              </div>
            ))}
          </div>
          <div
            data-d="modal"
            className="absolute inset-x-1.5 top-4 rounded-lg border border-white/15 bg-[#202c33] p-2 opacity-0 shadow-2xl"
          >
            <p className="text-[10px] font-semibold">Export chat</p>
            <p className="text-[8px] text-white/50">Chat: {OPEN_CHAT}</p>
            <div className="mt-1.5 flex gap-2">
              {FORMATS.map((format, index) => (
                <span
                  key={format}
                  data-d={`format-${index}`}
                  className="flex items-center gap-1 text-[8.5px]"
                >
                  <span className="flex size-2.5 items-center justify-center rounded-full border border-white/40">
                    {(index === 0 || index === PICKED_FORMAT) && (
                      <span
                        data-d={`format-dot-${index}`}
                        className="size-1.5 rounded-full bg-[#25d366]"
                      />
                    )}
                  </span>
                  {format}
                </span>
              ))}
            </div>
            <div className="mt-1.5 space-y-1">
              {EXPORT_OPTIONS.map((option) => (
                <div
                  key={option.label}
                  className="flex items-center gap-1.5 text-[8.5px] text-white/80"
                >
                  <Check on={option.on} />
                  {option.label}
                </div>
              ))}
            </div>
            <div className="mt-2 flex justify-end gap-1.5 text-[8.5px]">
              <span className="rounded px-2 py-0.5 text-white/70">Cancel</span>
              <span
                data-d="export-go"
                className="rounded bg-[#25d366] px-2 py-0.5 font-semibold text-[#111b21]"
              >
                Export
              </span>
            </div>
          </div>
          <div
            data-d="toast"
            className="absolute inset-x-6 bottom-2 rounded-md bg-[#e9edef] px-2 py-1 text-center text-[8.5px] font-medium text-[#111b21] opacity-0"
          >
            Chat exported
          </div>
        </div>
      </div>
      <div className="flex justify-between border-t border-white/10 px-2 py-1 text-[7.5px] text-white/50">
        <span>One Panel</span>
        <span>
          <span data-d="active">{DEFAULT_ACTIVE}</span> active
        </span>
      </div>
    </div>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label="ChatBoost opening its drawer in WhatsApp Web, blurring private content with Private Mode and exporting the open chat as JSON"
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome url="https://web.whatsapp.com/">
        <div className="relative flex h-full bg-[#111b21] text-[#e9edef]">
          <div className="flex w-9 shrink-0 flex-col items-center gap-2.5 border-r border-white/10 bg-[#202c33] pt-2.5">
            <MessageCircleIcon className="size-3.5 text-white/70" />
            <span className="size-3.5 rounded-full border border-white/40" />
            <UsersIcon className="size-3.5 text-white/50" />
            <span
              data-d="launcher"
              className="flex size-5 items-center justify-center rounded-full bg-[#25d366] shadow-[0_0_10px_rgba(37,211,102,0.5)]"
            >
              <PlusIcon className="size-3 text-[#111b21]" strokeWidth={3} />
            </span>
          </div>
          <div className="w-[188px] shrink-0 border-r border-white/10">
            <div className="p-1.5">
              <span className="block rounded-md bg-[#202c33] px-2 py-1 text-[8.5px] text-white/40">
                Search
              </span>
            </div>
            {CHATS.map((chat, index) => (
              <div
                key={chat.name}
                className={`flex items-center gap-1.5 px-2 py-1.5 ${index === 0 ? 'bg-[#2a3942]' : ''}`}
              >
                <span
                  data-d="blur-photo"
                  className="size-6 shrink-0 rounded-full"
                  style={{ background: chat.color }}
                />
                <span className="min-w-0 flex-1 border-b border-white/5 pb-1">
                  <span data-d="blur-name" className="block text-[9px] font-medium">
                    {chat.name}
                  </span>
                  <span data-d="blur-preview" className="block truncate text-[8px] text-white/50">
                    {chat.preview}
                  </span>
                </span>
              </div>
            ))}
          </div>
          <div className="flex min-w-0 flex-1 flex-col bg-[#0b141a]">
            <div className="flex items-center gap-1.5 bg-[#202c33] px-2 py-1.5">
              <span
                data-d="blur-photo"
                className="size-5 rounded-full"
                style={{ background: CHATS[0].color }}
              />
              <span data-d="blur-name" className="flex-1 text-[9.5px] font-medium">
                {OPEN_CHAT}
              </span>
              <span
                title="Export chat"
                className="flex size-4 items-center justify-center rounded-full bg-white/10"
              >
                <FileJsonIcon className="size-2.5 text-white/70" />
              </span>
            </div>
            <div className="flex-1 space-y-1.5 p-2">
              {MESSAGES.map((message, index) => (
                <div
                  key={message.text}
                  data-d={`bubble-${index}`}
                  className={`w-fit max-w-[85%] rounded-md px-1.5 py-1 text-[8.5px] ${
                    message.me ? 'ml-auto bg-[#005c4b]' : 'bg-[#202c33]'
                  }`}
                >
                  {message.who && (
                    <span className="block text-[7.5px] font-semibold text-[#53bdeb]">
                      {message.who}
                    </span>
                  )}
                  <span data-d={`blur-msg bubble-text-${index}`} className="block">
                    {message.text}
                  </span>
                </div>
              ))}
            </div>
            <div className="bg-[#202c33] p-1.5">
              <span className="block rounded-md bg-[#2a3942] px-2 py-1 text-[8.5px] text-white/80">
                <span data-d="blur-composer" className="block">
                  Sending the contract now
                </span>
              </span>
            </div>
          </div>
          <Drawer />
          <div
            data-d="file"
            className="absolute right-2 top-2 flex items-center gap-1.5 rounded-lg bg-white px-2 py-1.5 text-[#111b21] opacity-0 shadow-lg"
          >
            <FileJsonIcon className="size-4 text-[#25d366]" />
            <span>
              <span className="block text-[8.5px] font-semibold">{FILE}</span>
              <span className="block text-[8px] text-[#64748b]">Saved to Downloads</span>
            </span>
          </div>
        </div>
      </BrowserChrome>
    </DemoStage>
  )
}
